cd "$(dirname "$0")" && python3 render.py >/dev/null
for n in logical physical data-model; do sed 's/width="36in" height="24in"/width="2592" height="1728"/' $n-archD.svg > /tmp/$n.svg; google-chrome --headless=new --no-sandbox --disable-gpu --hide-scrollbars --force-device-scale-factor=2 --window-size=2592,1728 --screenshot=$n-archD.png file:///tmp/$n.svg 2>/dev/null; google-chrome --headless=new --no-sandbox --disable-gpu --hide-scrollbars --window-size=2592,1728 --screenshot=/tmp/$n-1x.png file:///tmp/$n.svg 2>/dev/null; printf '<html><head><style>@page{size:36in 24in;margin:0}body{margin:0}</style></head><body>%s</body></html>' "$(cat $n-archD.svg)" > /tmp/$n.html; google-chrome --headless=new --no-sandbox --disable-gpu --no-pdf-header-footer --print-to-pdf=$n-archD.pdf file:///tmp/$n.html 2>/dev/null; done
